// Neon (serverless Postgres) on the business's own API key: every operation of Neon's API (projects, branches,
// databases, roles, compute endpoints, snapshots, Neon Auth, storage buckets, functions, logs, billing, orgs),
// plus run_sql, which queries a database over Neon's HTTP SQL endpoint. actions.json is generated by
// `bun scripts/openapi-actions.ts neon`; COVERAGE.md says what's left out.
import { z } from "zod";
import { AppsError } from "../../types";
import type { OwnApp } from "../index";
import { type Api, call, specActions } from "../openapi";

const api: Api = {
  name: "Neon",
  base: "https://console.neon.tech/api/v2",
  tokenHelp: "console.neon.tech → Account settings → API keys",
};

const runSql = {
  description:
    "Run SQL on a Neon database and get the rows back: SELECTs, INSERT/UPDATE/DELETE, CREATE TABLE, anything Postgres takes. One statement per call; use $1, $2… with params for values instead of pasting them into the query.",
  input: z.object({
    project_id: z.string().min(1).describe("The project, from list_projects"),
    query: z.string().min(1).describe('One SQL statement, e.g. "select * from orders where status = $1 limit 50"'),
    params: z.array(z.unknown()).optional().describe("Values for $1, $2… in order"),
    branch_id: z.string().optional().describe("The branch, from list_project_branches (default: the project's default branch)"),
    database_name: z.string().default("neondb").describe("The database, from list_project_branch_databases (default neondb, what a new project gets)"),
    role_name: z.string().default("neondb_owner").describe("The Postgres role to run as, from list_project_branch_roles (default neondb_owner)"),
  }),
  async run(i: { project_id: string; query: string; params?: unknown[]; branch_id?: string; database_name: string; role_name: string }, key: string) {
    const { uri } = (await call(
      api,
      key,
      { method: "GET", path: "/projects/{project_id}/connection_uri", query: ["branch_id", "database_name", "role_name"], headers: [] },
      i,
    )) as { uri: string };
    // the HTTP SQL endpoint is the compute's host with its first label swapped for "api", as Neon's own driver does
    const host = new URL(uri).hostname.replace(/^[^.]+\./, "api.");
    const res = await fetch(`https://${host}/sql`, {
      method: "POST",
      headers: { "Neon-Connection-String": uri, "Content-Type": "application/json" },
      body: JSON.stringify({ query: i.query, params: i.params ?? [] }),
    });
    const out = (await res.json().catch(() => ({}))) as { message?: string; command?: string; rowCount?: number; rows?: unknown[]; fields?: { name: string }[] };
    if (!res.ok) throw new AppsError(`Neon: ${out.message ?? res.statusText} (${res.status})`);
    return { command: out.command, rowCount: out.rowCount, columns: out.fields?.map((f) => f.name), rows: out.rows };
  },
};

export const neon: OwnApp = {
  app: "neon",
  name: "Neon",
  logo: "/logos/neon.svg",
  keyField: {
    label: "API key",
    help: "console.neon.tech → Account settings → API keys → Create new API key (or an organization's key, from its settings, to reach its projects).",
    placeholder: "napi_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx",
  },
  // answers for personal, organization and project keys alike
  async check(key) {
    await call(api, key, { method: "GET", path: "/auth", query: [], headers: [] }, {});
  },
  actions: { ...(await specActions(new URL("./actions.json", import.meta.url), api)), run_sql: runSql },
};
